import java.util.*;
import java.io.*;

public class Main {
    static final int MOD1 = 998244353;
    static final int MOD2 = 1000000007;
    static final int MAXN = 2000000;
    static final int MAX = 1000000;
    static long n, c;
    static int total, answer, limit;
    static int[] power = new int[9];
    static int[] sumArr = new int[9];
    static List<Integer>[] vec = new ArrayList[9];

    static {
        for (int i = 0; i < 9; i++) {
            vec[i] = new ArrayList<>();
        }
    }

    static int subtract(int x, int y, int m) {
        return (x - y < 0) ? x - y + m : x - y;
    }

    static int addMod(int x, int y, int m) {
        return (x + y >= m) ? x + y - m : x + y;
    }

    static void dfs(int position, long current) {
        if (current <= n) {
            total++;
            int x = subtract(total, (int) current, MOD1);
            vec[position - 1].add(x);
            sumArr[position - 1] = addMod(sumArr[position - 1], x, MOD2);
        }
        if (position > 6) return;
        for (int i = 0; i <= 9; i++) {
            dfs(position + 1, current * 10 + i);
        }
    }

    static void process(int position, long current) {
        if (current > n) return;
        if (position > 1) {
            if (10L * current * MAX > n && 1L * (current + 1) * MAX - 1 <= n) {
                for (int i = 0; i < 7; i++) {
                    int x = ((int) ((c - 1L * current * power[i]) % MOD1) + MOD1) % MOD1;
                    List<Integer> arr = vec[i];
                    int p = lowerBound(arr, MOD1 - x);
                    answer = addMod(answer, addMod((int) ((1L * x * arr.size()) % MOD2), sumArr[i], MOD2), MOD2);
                    answer = subtract(answer, (int) ((1L * MOD1 * (arr.size() - p)) % MOD2), MOD2);
                }
                c += total;
                return;
            }
            c++;
            answer = addMod(answer, (int) (((c - current) % MOD1 + MOD1) % MOD1), MOD2);
        }
        int start = (position == 1) ? 1 : 0;
        for (int i = start; i <= 9; i++) {
            process(position + 1, current * 10 + i);
        }
    }

    static int lowerBound(List<Integer> list, int value) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= value) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Long.parseLong(br.readLine());
        for (int i = 1; i < 9; i++) {
            power[i] = 10 * power[i - 1];
        }
        dfs(1, 0);
        for (int i = 0; i < 7; i++) {
            Collections.sort(vec[i]);
        }
        process(1, 0);
        System.out.println(answer);
    }
}
